{"explanation":"A triangle’s area is half its base times its height: A = ½bh. Scaling by k multiplies both the base and the perpendicular height by k, so the new area is ½(kb)(kh) = k²A. Drag the yellow vertex to see both lengths—and their product—change together.","manimCode":"const title = new Text({ text: 'Two scaled lengths → a squared area', fontSize: 32, color: WHITE });
title.moveTo([0, 3.25, 0]);
const formula = new MathTex({ latex: 'A_{\mathrm{new}}=\\frac12(kb)(kh)=k^2 A_{\mathrm{original}}' });
await formula.waitForRender();
formula.moveTo([0, 2.65, 0]);
scene.add(title, formula);

let k = 1.5;
const base = 2;
const height = 1.5;
const originalArea = base * height / 2;
const origin = [0.2, -1.3, 0];
const originalVertices = [[-4.8, -1.3, 0], [-2.8, -1.3, 0], [-4.1, 0.2, 0]];
const original = new Polygon({ vertices: originalVertices, color: BLUE });
original.setFill(BLUE, 0.28);
const originalHeight = new DashedLine({ start: [-4.1, -1.3, 0], end: [-4.1, 0.2, 0], color: TEAL });
const originalBaseLabel = new Text({ text: 'b = 2', fontSize: 24, color: BLUE });
originalBaseLabel.moveTo([-3.8, -1.75, 0]);
const originalHeightLabel = new Text({ text: 'h = 1.5', fontSize: 22, color: TEAL });
originalHeightLabel.moveTo([-5.45, -0.45, 0]);
const originalLabel = new Text({ text: 'Original area = 1.50', fontSize: 24, color: BLUE });
originalLabel.moveTo([-3.7, 0.85, 0]);

const enlarged = new Polygon({ vertices: [origin, [3.2, -1.3, 0], [1.25, 0.95, 0]], color: GREEN });
enlarged.setFill(GREEN, 0.28);
const scaledHeight = new DashedLine({ start: origin, end: [0.2, 1, 0], color: TEAL });
const handle = new Dot({ point: [1.25, 0.95, 0], radius: 0.14, color: YELLOW });
const scaledBaseLabel = new Text({ text: '', fontSize: 24, color: GREEN });
const scaledHeightLabel = new Text({ text: '', fontSize: 22, color: TEAL });
const readout = new Text({ text: '', fontSize: 24, color: GREEN });
readout.moveTo([2.5, 2.05, 0]);
const ratio = new Text({ text: '', fontSize: 27, color: YELLOW });
ratio.moveTo([0, -2.55, 0]);
const hint = new Text({ text: 'Drag the yellow vertex: base and height scale together', fontSize: 21, color: GRAY });
hint.moveTo([0, -3.25, 0]);
scene.add(original, originalHeight, originalBaseLabel, originalHeightLabel, originalLabel);
scene.add(enlarged, scaledHeight, handle, scaledBaseLabel, scaledHeightLabel, readout, ratio, hint);

function update() {
  const apex = [origin[0] + 0.7 * k, origin[1] + height * k, 0];
  const rightCorner = [origin[0] + base * k, origin[1], 0];
  enlarged.setVertices([origin, rightCorner, apex]);
  scaledHeight.setStart([apex[0], origin[1], 0]);
  scaledHeight.setEnd(apex);
  handle.moveTo(apex);
  scaledBaseLabel.setText('kb = ' + (base * k).toFixed(2));
  scaledBaseLabel.moveTo([origin[0] + base * k / 2, -1.75, 0]);
  scaledHeightLabel.setText('kh = ' + (height * k).toFixed(2));
  scaledHeightLabel.moveTo([rightCorner[0] + 0.65, origin[1] + height * k / 2, 0]);
  readout.setText('k = ' + k.toFixed(2) + '   Area = ' + (originalArea * k * k).toFixed(2));
  ratio.setText('Length factor: ' + k.toFixed(2) + '    Area factor: ' + (k * k).toFixed(2));
}
update();
makeDraggable(handle, scene, {
  onDrag: (mob, pos) => {
    const dx = pos[0] - origin[0];
    const dy = pos[1] - origin[1];
    k = Math.max(0.55, Math.min(2, (0.7 * dx + height * dy) / (0.7 * 0.7 + height * height)));
    update();
  }
});
await scene.wait(999999);"}

